  ExamQuestion(1, 'Araç arızalanıp yolda kaldığında ne yapılmalıdır?', ['Araç olduğu yerde bırakılıp gidilir', 'Dörtlü ikaz yakılır, yansıtıcı (reflektör) gelen trafiğe karşı konulur', 'Farlar söndürülür', 'Yolun ortasında tamir yapılır'], 1, 'Mümkünse araç yol dışına alınır, dörtlüler yakılır ve yansıtıcı uygun mesafeye yerleştirilir.'),
  ExamQuestion(1, 'Şerit değiştirirken ilk yapılması gereken nedir?', ['Hemen direksiyonu çevirmek', 'Aynalardan kontrol edip sinyal vermek', 'Korna çalmak', 'Fren yapmak'], 1, 'Ayna ve kör nokta kontrolü yapılır, sinyal verilir, güvenliyse şerit değiştirilir.'),
  ExamQuestion(1, 'Sağa dönüş nasıl yapılmalıdır?', ['Sol şeritten geniş bir kavisle', 'En sağ şeritten, kısa bir kavisle', 'Orta şeritten', 'Ters yönden'], 1, 'Sağa dönüşler en sağ şeritten, yolun sağ kenarına yakın olarak yapılır.'),
  ExamQuestion(1, 'Sola dönüş yapacak sürücü dönüşe hangi şeritten hazırlanır?', ['En sağ şerit', 'Kendi yönündeki en sol şerit', 'Karşı yön şeridi', 'Banket'], 1, 'Sola dönecek sürücü kendi yönündeki en sol şeride geçer, sinyal verir.'),
  ExamQuestion(1, 'Okul taşıtı öğrenci indirip bindirmek için durmuş ve ışıklarını yakıyorsa diğer sürücüler ne yapmalıdır?', ['Hızla geçmelidir', 'Yavaşlayıp dikkatle, gerekirse durarak hareket etmelidir', 'Korna çalmalıdır', 'Sollamalıdır'], 1, 'Çocukların ani hareketlerine karşı yavaşlanır, gerekirse durulur.'),
  ExamQuestion(1, 'Yağışlı havada fren mesafesi nasıl değişir?', ['Kısalır', 'Uzar', 'Değişmez', 'Sıfırlanır'], 1, 'Islak zeminde tutunma azalır, fren mesafesi uzar; hız düşürülüp mesafe artırılmalıdır.'),
  ExamQuestion(1, 'Yokuş aşağı inerken hangi davranış doğrudur?', ['Vites boşa alınır', 'Uygun küçük viteste motor freninden yararlanılır', 'Sürekli frene basılır', 'Kontak kapatılır'], 1, 'Uzun inişlerde motor freni kullanılır; sürekli fren balataları ısıtıp etkisini azaltır.'),
  ExamQuestion(1, 'Dar bir köprüye karşılıklı iki araç geliyorsa öncelik kimindir?', ['Köprüye önce giren araca', 'Hızlı olana', 'Büyük olana', 'Korna çalana'], 0, 'Dar köprü ve geçitlerde, köprüye önce giren aracın geçişi beklenir.'),
  ExamQuestion(1, 'Dar ve eğimli yolda karşılaşan araçlardan hangisi yol vermelidir?', ['İnen araç', 'Çıkan araç', 'Büyük araç', 'Yükü az olan'], 0, 'Kural olarak inen araç, çıkan araca yol verir (çıkan aracın kalkışı zordur).'),
  ExamQuestion(1, 'Gece yerleşim yeri dışında park eden araçta hangi lambalar yakılır?', ['Uzun farlar', 'Park lambaları', 'Sis lambaları', 'Hiçbiri'], 1, 'Aydınlatılmamış yolda park eden araç park lambalarıyla görünür kılınır.'),
  ExamQuestion(1, 'Yaya geçidi bulunmayan yerde yaya karşıya geçmek istiyorsa sürücü ne yapmalıdır?', ['Korna çalıp hızlanmalıdır', 'Dikkatli olup yayanın güvenle geçmesine imkân tanımalıdır', 'Selektör yapmalıdır', 'Yayayı uyarıp geçmelidir'], 1, 'Sürücüler yayalara karşı her zaman dikkatli ve saygılı olmalıdır.'),
  ExamQuestion(1, 'Ehliyetsiz bir kişiye araç kullandırmak nasıldır?', ['Serbesttir', 'Yasaktır', 'Sadece gündüz serbesttir', 'Akrabaya serbesttir'], 1, 'Sürücü belgesi olmayan kişiye araç kullandırmak yasaktır ve cezası vardır.'),
  ExamQuestion(1, '"Taşıt giremez" levhası ne anlama gelir?', ['Sadece kamyonlar giremez', 'Hiçbir taşıt giremez', 'Sadece bisikletler girer', 'Park yeridir'], 1, 'Bu levha, her iki yönden taşıt girişinin yasak olduğunu bildirir.'),
  ExamQuestion(1, '"Girilmez" levhası (kırmızı zemin üzerinde beyaz yatay şerit) ne bildirir?', ['Bu yönden girmek yasaktır', 'Tek yönlü yol sonu', 'Park etmek serbesttir', 'Duraklamak yasaktır'], 0, 'Levhanın bulunduğu yönden yola girmek yasaktır.'),
  ExamQuestion(1, 'Okul geçidinde görevli bulunuyorsa sürücü kime uyar?', ['Kendi kararına', 'Okul geçidi görevlisinin işaretine', 'Arkadaki araca', 'Yayaların sesine'], 1, 'Okul geçidi görevlilerinin işaretlerine uyulması zorunludur.'),
  ExamQuestion(1, 'Kavşağa yaklaşırken hızla ilgili doğru davranış hangisidir?', ['Hızı artırmak', 'Hızı azaltıp dikkatli olmak', 'Aynı hızla devam etmek', 'Korna çalarak girmek'], 1, 'Kavşaklar kazaların sık olduğu yerlerdir; yaklaşırken hız azaltılır.'),
  ExamQuestion(1, 'Arkadan gelen araç sollamak istiyorsa öndeki sürücü ne yapmalıdır?', ['Hızını artırmalıdır', 'Sağa yanaşıp hızını artırmamalıdır', 'Sola kaymalıdır', 'Fren yapıp durmalıdır'], 1, 'Sollanan araç sürücüsü sağa yanaşır ve sollama bitinceye kadar hızını artırmaz.'),
  ExamQuestion(1, 'Gece sollama yapılırken uyarı için ne kullanılabilir?', ['Uzun süre korna', 'Selektör (kısa-uzun far)', 'Dörtlü ikaz', 'Sis lambası'], 1, 'Gece uyarı amacıyla selektör kullanılabilir.'),
  ExamQuestion(1, 'Engelli park yerine park etmek isteyen engelli olmayan sürücü ne yapmalıdır?', ['Kısa süreliğine park edebilir', 'Park etmemelidir', 'Dörtlüleri yakıp park edebilir', 'Gece park edebilir'], 1, 'Engelliler için ayrılmış yerlere başkalarının park etmesi yasaktır.'),
  ExamQuestion(1, 'Viraja yaklaşırken doğru davranış hangisidir?', ['Virajın içinde sert fren yapmak', 'Virajdan önce hızı azaltmak', 'Virajda hızlanmak', 'Virajda sollamak'], 1, 'Hız virajdan önce düşürülür; viraj içinde sert fren kaymaya yol açabilir.'),
  ExamQuestion(1, 'Bisikletliyi geçerken sürücü ne yapmalıdır?', ['Yakından geçmelidir', 'Yeterli yan mesafe bırakarak geçmelidir', 'Korna çalarak sıkıştırmalıdır', 'Hızlanmalıdır'], 1, 'Bisikletlilere yeterli yan mesafe bırakılır; ani rüzgâr veya engel onları savurabilir.'),
  ExamQuestion(1, 'Buzlu yolda kayma başladığında yapılması gereken nedir?', ['Sert fren yapmak', 'Ani direksiyon hareketlerinden kaçınıp kaymanın yönüne doğru direksiyonu düzeltmek', 'Gaza basmak', 'El frenini çekmek'], 1, 'Ani fren ve direksiyon hareketlerinden kaçınılır; araç kontrollü şekilde düzeltilir.'),
  ExamQuestion(1, 'Sürücü belgesi olmadan araç kullanıldığının tespiti hâlinde ne olur?', ['Uyarı verilir', 'İdari para cezası uygulanır ve araç trafikten men edilebilir', 'Hiçbir şey olmaz', 'Sadece not alınır'], 1, 'Sürücü belgesiz araç kullanmak cezai yaptırımı olan bir ihlaldir.'),
  ExamQuestion(1, 'Otoyolda yapılması yasak olan davranış hangisidir?', ['Sağ şeritten gitmek', 'Geri gitmek ve U dönüşü yapmak', 'Hız sınırına uymak', 'Takip mesafesi bırakmak'], 1, 'Otoyolda geri gitmek, U dönüşü yapmak ve emniyet şeridinde gereksiz durmak yasaktır.'),
  ExamQuestion(1, 'Emniyet şeridi ne amaçla kullanılır?', ['Sollama için', 'Arıza veya acil durumlarda durmak için', 'Trafik sıkışınca ilerlemek için', 'Park etmek için'], 1, 'Emniyet şeridi yalnız zorunlu durumlarda ve acil durum araçlarınca kullanılır.'),
  ExamQuestion(1, 'Şehir içinde korna kullanımıyla ilgili doğru ifade hangisidir?', ['Selamlaşmak için çalınabilir', 'Zorunlu hâller dışında kullanılmamalıdır', 'Trafik sıkışınca çalınmalıdır', 'Gece serbesttir'], 1, 'Korna yalnızca tehlikeyi önlemek gibi zorunlu hâllerde kullanılır.'),
  ExamQuestion(1, 'Araç muayenesi neden yaptırılır?', ['Sadece vergi için', 'Aracın güvenli ve kurallara uygun olduğunun kontrolü için', 'Plaka değiştirmek için', 'Sigorta indirimi için'], 1, 'Periyodik muayene; fren, far, lastik, egzoz gibi güvenlik unsurlarının uygunluğunu denetler.'),
  ExamQuestion(1, 'Zorunlu mali sorumluluk (trafik) sigortası neyi karşılar?', ['Sürücünün kendi aracının tüm hasarını', 'Kazada üçüncü kişilere verilen zararları (belli limitlerde)', 'Aracın yakıt masrafını', 'Trafik cezalarını'], 1, 'Trafik sigortası, üçüncü kişilere verilen maddi ve bedeni zararları poliçe limitleri içinde karşılar.'),
  ExamQuestion(1, 'Kazada yaralı varsa sürücünün yasal yükümlülüğü nedir?', ['Olay yerinden uzaklaşmak', 'Durmak, yardım çağırmak ve olay yerini korumak', 'Sadece fotoğraf çekmek', 'Aracı hemen çekmek'], 1, 'Yaralanmalı kazada sürücü durur, 112\'ye bildirir, ilk yardım ve olay yeri güvenliği sağlar.'),
  ExamQuestion(1, 'Maddi hasarlı kazada taraflar anlaşırsa ne yapılabilir?', ['Kaza tespit tutanağı birlikte doldurulabilir', 'Hiçbir işlem yapılmaz', 'Araçlar terk edilir', 'Ehliyetler değiştirilir'], 0, 'Yalnız maddi hasarlı kazalarda taraflar kaza tespit tutanağını birlikte doldurabilir.'),
  ExamQuestion(1, 'Kırmızı ışıkta beklerken yeşil yanınca kavşakta hâlâ araç varsa ne yapılır?', ['Hemen hareket edilir', 'Kavşak boşalınca dikkatle hareket edilir', 'Korna çalınır', 'Geri gidilir'], 1, 'Yeşil ışık geçiş hakkı verir ama kavşaktaki araçların çıkması beklenir.'),
  ExamQuestion(1, 'Sağanak yağışta su birikintisine hızlı girildiğinde oluşabilecek tehlike nedir?', ['Lastiklerin yolla temasını kaybetmesi (kızaklama)', 'Motorun soğuması', 'Yakıt tasarrufu', 'Farların parlaması'], 0, 'Lastik ile yol arasında su tabakası oluşur (aquaplaning), direksiyon ve fren etkisizleşir.'),
  ExamQuestion(1, 'Sürücünün yorgunluk belirtisi fark ettiğinde yapması gereken nedir?', ['Kahve içip devam etmek', 'Güvenli bir yerde durup dinlenmek', 'Hızı artırmak', 'Camı açıp devam etmek'], 1, 'Yorgunlukta en güvenli çözüm durup dinlenmektir; uzun yolda yaklaşık 2 saatte bir mola önerilir.'),
  ExamQuestion(1, 'Kavşakta dönüş yapacak araçlar ile düz gidecek araçlar arasında öncelik nasıldır?', ['Dönen araç önceliklidir', 'Kural olarak düz giden ve karşıdan gelen araçlara yol verilir', 'Büyük araç önceliklidir', 'Önce korna çalan geçer'], 1, 'Sola dönen sürücü karşı yönden düz gelen araçlara yol verir.'),
  ExamQuestion(1, 'Araçla yük taşırken yükle ilgili doğru ifade hangisidir?', ['Yük sabitlenmeden taşınabilir', 'Yük düşmeyecek, dökülmeyecek şekilde sabitlenmelidir', 'Plakayı kapatabilir', 'Farları kapatabilir'], 1, 'Yük güvenle bağlanır; plaka, ışıklar ve görüş alanı kapatılmaz.'),
  ExamQuestion(1, 'Yeşil ışıkta sağa dönerken yaya geçidinde yaya varsa ne yapılır?', ['Yayaya yol verilir', 'Korna çalınıp geçilir', 'Yaya beklemelidir', 'Hızlanılır'], 0, 'Dönüş yapan sürücüler, geçitten geçen yayalara yol vermek zorundadır.'),
  ExamQuestion(2, 'Motorun soğutma sisteminde aşırı ısınmayı önleyen sıvı hangisidir?', ['Fren hidroliği', 'Antifrizli soğutma suyu', 'Motor yağı', 'Cam suyu'], 1, 'Radyatördeki antifrizli su motoru soğutur ve kışın donmayı önler.'),
  ExamQuestion(2, 'Benzinli motorlarda yakıt-hava karışımını ateşleyen parça hangisidir?', ['Enjektör', 'Buji', 'Termostat', 'Debriyaj'], 1, 'Benzinli motorlarda karışım bujinin kıvılcımıyla ateşlenir.'),
  ExamQuestion(2, 'Dizel motorlarda yakıt nasıl ateşlenir?', ['Buji kıvılcımıyla', 'Sıkıştırılarak ısınan havaya püskürtülerek', 'Akünün ateşlemesiyle', 'Kibritle'], 1, 'Dizel motorlarda yakıt, sıkıştırılarak ısınmış havaya püskürtülünce kendiliğinden tutuşur.'),
  ExamQuestion(2, 'Motor yağı seviyesi hangi parça ile kontrol edilir?', ['Termometre', 'Yağ çubuğu', 'Hız göstergesi', 'Devir saati'], 1, 'Araç düz zeminde ve motor durmuşken yağ çubuğuyla kontrol edilir.'),
  ExamQuestion(2, 'Gösterge panelinde yağ basıncı uyarı lambası yanarsa ne yapılmalıdır?', ['Yola devam edilir', 'Araç güvenli yerde durdurulup motor kapatılır', 'Hızlanılır', 'Cam suyu eklenir'], 1, 'Yağ basıncı düşükken çalışmak motora ciddi zarar verir; durulup kontrol edilir.'),
  ExamQuestion(2, 'Aracın elektrik ihtiyacını motor çalışırken karşılayan ve aküyü şarj eden parça hangisidir?', ['Marş motoru', 'Alternatör (şarj dinamosu)', 'Radyatör', 'Rot'], 1, 'Alternatör motor çalışırken elektrik üretir ve aküyü şarj eder.'),
  ExamQuestion(2, 'Motoru ilk hareket için döndüren parça hangisidir?', ['Alternatör', 'Marş motoru', 'Su pompası', 'Debriyaj'], 1, 'Kontak çevrilince marş motoru motoru döndürerek çalıştırır.'),
  ExamQuestion(2, 'Motor sıcaklığını belli seviyede tutmak için soğutma suyunun dolaşımını ayarlayan parça hangisidir?', ['Termostat', 'Buji', 'Karbüratör', 'Amortisör'], 0, 'Termostat, motor ısınana kadar suyun radyatöre gitmesini kısıtlar.'),
  ExamQuestion(2, 'Debriyajın görevi nedir?', ['Aracı durdurmak', 'Motorun gücünü vites kutusuna bağlayıp ayırmak', 'Yakıt püskürtmek', 'Farları yakmak'], 1, 'Debriyaj, vites değişimi için motorla şanzıman arasındaki bağlantıyı keser ve bağlar.'),
  ExamQuestion(2, 'ABS fren sisteminin temel faydası nedir?', ['Fren mesafesini her zaman sıfırlar', 'Sert frende tekerleklerin kilitlenmesini önleyerek direksiyon hâkimiyetini korur', 'Yakıt tasarrufu sağlar', 'Lastikleri şişirir'], 1, 'ABS tekerlek kilitlenmesini önler; sürücü frenlerken direksiyonla yönlendirme yapabilir.'),
  ExamQuestion(2, 'Fren hidroliği seviyesi azalırsa ne olabilir?', ['Frenler daha iyi tutar', 'Fren etkinliği azalır', 'Motor daha hızlı çalışır', 'Farlar söner'], 1, 'Hidrolik eksikliği frenlerin zayıflamasına yol açar; sızıntı kontrol edilmelidir.'),
  ExamQuestion(2, 'Binek araç lastiklerinde yasal en az diş derinliği kaç milimetredir?', ['0,5', '1,6', '3', '5'], 1, 'Diş derinliği 1,6 mm\'nin altına inen lastik değiştirilmelidir; kışın daha derin diş önerilir.'),
  ExamQuestion(2, 'Lastik hava basıncı ne zaman ölçülmelidir?', ['Uzun yoldan hemen sonra', 'Lastikler soğukken', 'Yağmurda', 'Gece yarısı'], 1, 'Basınç lastikler soğukken ölçülür; değer araç kılavuzunda yazar.'),
  ExamQuestion(2, 'Amortisörlerin görevi nedir?', ['Motoru soğutmak', 'Yoldan gelen sarsıntıları sönümleyip tekerleklerin yola tutunmasını sağlamak', 'Yakıtı süzmek', 'Aküyü şarj etmek'], 1, 'Bozuk amortisör yol tutuşu ve fren mesafesini olumsuz etkiler.'),
  ExamQuestion(2, 'Rot-balans ayarı bozuk araçta görülen belirti hangisidir?', ['Aracın bir yana çekmesi ve lastiklerin düzensiz aşınması', 'Farların parlaması', 'Yakıtın azalması', 'Kornanın çalmaması'], 0, 'Rot-balans bozukluğu direksiyonda titreme, çekme ve düzensiz lastik aşınmasına yol açar.'),
  ExamQuestion(2, 'Hava filtresinin tıkalı olması neye yol açar?', ['Motor gücünün azalması ve yakıt tüketiminin artması', 'Frenlerin güçlenmesi', 'Akünün dolması', 'Farların yanması'], 0, 'Motora yeterli temiz hava gitmezse yanma bozulur, güç düşer.'),
  ExamQuestion(2, 'Akü kutup başlarının oksitlenmesi neye yol açabilir?', ['Marşın zor basması', 'Frenlerin kilitlenmesi', 'Motorun soğuması', 'Direksiyonun ağırlaşması'], 0, 'Oksitlenme elektrik iletimini zayıflatır; marş zor basar.'),
  ExamQuestion(2, 'Katalitik konvertörün görevi nedir?', ['Egzoz gazındaki zararlı maddeleri azaltmak', 'Motoru soğutmak', 'Yakıtı ısıtmak', 'Fren gücünü artırmak'], 0, 'Katalitik konvertör egzozdaki zararlı gazları daha az zararlı gazlara dönüştürür.'),
  ExamQuestion(2, 'Gösterge panelinde akü (şarj) uyarı lambası yol sırasında yanarsa ne anlaşılır?', ['Şarj sisteminde arıza olabilir', 'Yakıt bitmiştir', 'Kapı açıktır', 'Kemer takılmamıştır'], 0, 'Alternatör veya kayış arızası olabilir; akü kısa sürede boşalır.'),
  ExamQuestion(2, 'Triger kayışı koparsa ne olabilir?', ['Motor ciddi hasar görebilir ve stop eder', 'Sadece radyo susar', 'Klima güçlenir', 'Hiçbir şey olmaz'], 0, 'Triger kayışı/zinciri bakım aralığında değiştirilmezse kopması motora ağır zarar verebilir.'),
  ExamQuestion(2, 'Soğuk havada motor çalıştırıldıktan sonra doğru davranış hangisidir?', ['Hemen yüksek devirde gaza basmak', 'Yavaş ve düşük devirde sürüşe başlamak', 'Motoru uzun süre rölantide bırakmak zorunludur', 'Motor yağını boşaltmak'], 1, 'Motor ısınana kadar yüksek devirden kaçınılır; modern araçlar kısa bekleme sonrası sakin sürüşle ısınır.'),
  ExamQuestion(2, 'Silecek lastiklerinin iyi silmemesi hâlinde ne yapılmalıdır?', ['Silecekler kullanılmaz', 'Silecek lastikleri değiştirilir', 'Cama yağ sürülür', 'Hız artırılır'], 1, 'Yıpranmış silecek görüşü azaltır; lastikleri yenilenmelidir.'),
  ExamQuestion(2, 'Ekonomik sürüş için hangisi doğrudur?', ['Ani hızlanma ve frenden kaçınmak', 'Sürekli yüksek devirde gitmek', 'Lastik basıncını düşük tutmak', 'Gereksiz yükü araçta taşımak'], 0, 'Akıcı sürüş, uygun vites ve doğru lastik basıncı yakıt tüketimini azaltır.'),
  ExamQuestion(3, 'Trafikte "empati" ne demektir?', ['Kendini diğer yol kullanıcısının yerine koyabilmek', 'Hızlı araç kullanmak', 'Kurallara sadece polis varken uymak', 'Korna çalmak'], 0, 'Empati, diğer sürücü ve yayaların durumunu anlayarak davranmaktır.'),
  ExamQuestion(3, 'Trafikte öfkelenen sürücünün yapması gereken nedir?', ['Karşı sürücüyle tartışmak', 'Sakinleşip güvenli sürüşe odaklanmak', 'Takip etmek', 'Selektör yapmak'], 1, 'Öfke dikkati dağıtır; sakin kalmak kazaları önler.'),
  ExamQuestion(3, 'Yaşlı ya da engelli bir yaya karşıdan karşıya geçerken sürücü ne yapmalıdır?', ['Korna çalmalıdır', 'Sabırla beklemeli ve geçmesini kolaylaştırmalıdır', 'Yanından hızla geçmelidir', 'Selektör yapmalıdır'], 1, 'Saygılı sürücü, hareketi kısıtlı yayalara sabır gösterir.'),
  ExamQuestion(3, 'Trafik adabına uygun davranış hangisidir?', ['Sıkışık trafikte emniyet şeridinden ilerlemek', 'Sırayı beklemek ve diğerlerine yol vermek', 'Sürekli şerit değiştirmek', 'Çöpü camdan atmak'], 1, 'Sabır ve sıraya saygı, akışı ve güvenliği artırır.'),
  ExamQuestion(3, 'Araçtan dışarıya çöp atmak hakkında doğru ifade hangisidir?', ['Serbesttir', 'Çevreyi kirletir ve cezai yaptırımı vardır', 'Sadece otoyolda serbesttir', 'Gece serbesttir'], 1, 'Araçtan yola çöp atmak çevreyi kirletir ve diğer sürücüler için tehlikelidir.'),
  ExamQuestion(3, 'Su birikintisinin yanından geçerken yayalara karşı doğru davranış hangisidir?', ['Hızlanıp geçmek', 'Yavaşlayarak yayaları ıslatmamaya özen göstermek', 'Korna çalmak', 'Yaya yoluna çıkmak'], 1, 'Saygılı sürücü yavaşlayarak yayaları rahatsız etmez.'),
  ExamQuestion(3, 'Hatalı davranışını fark eden sürücünün tutumu nasıl olmalıdır?', ['Diğer sürücüyü suçlamak', 'Hatasını kabul edip özür dilemek (el işareti vb.)', 'Hızla uzaklaşmak', 'Tartışma başlatmak'], 1, 'Hatayı kabullenmek gerginliği azaltır.'),
  ExamQuestion(3, 'Ambulansa yol vermemek hangi değere aykırıdır?', ['Sadece kurala', 'Hem kurala hem de insan hayatına saygıya', 'Hiçbirine', 'Sadece estetiğe'], 1, 'Ambulansa yol vermek hayat kurtarabilir; hem yasal hem vicdani bir sorumluluktur.'),
  ExamQuestion(3, 'Uzun yol öncesinde sürücünün hazırlığıyla ilgili doğru olan hangisidir?', ['Uykusuz yola çıkmak', 'Dinlenmiş olarak, araç kontrollerini yapıp yola çıkmak', 'Yol boyunca mola vermemek', 'Alkol almak'], 1, 'Dinlenmiş sürücü ve kontrol edilmiş araç güvenli yolculuğun temelidir.'),
  ExamQuestion(3, 'Trafikte sabırlı olmanın faydası nedir?', ['Kaza riskinin ve stresin azalması', 'Daha çok ceza almak', 'Daha hızlı gitmek', 'Yakıt harcamak'], 0, 'Sabır, aceleci davranışlardan doğan kazaları önler.'),
  ExamQuestion(3, 'Gece karşıdan gelen sürücünün uzun farları gözünüzü alıyorsa ne yapılmalıdır?', ['Siz de uzun farlarınızı yakmak', 'Bakışı yolun sağ kenarına kaydırıp yavaşlamak', 'Selektörle cezalandırmak', 'Durup kavga etmek'], 1, 'Bakış sağ kenara kaydırılır, hız azaltılır; karşılık vermek iki tarafı da tehlikeye atar.'),
  ExamQuestion(3, 'Yayalara karşı saygılı sürücü hangisini yapar?', ['Yaya geçidinde durur ve yol verir', 'Yaya geçidinde park eder', 'Kaldırıma park eder', 'Yayaları korna ile uyarır'], 0, 'Yaya geçitleri yayaların güvenli alanıdır.'),
  ExamQuestion(3, 'Trafik kuralları neden uyulması gereken kurallardır?', ['Sadece ceza almamak için', 'Herkesin can ve mal güvenliği için', 'Sadece sınavı geçmek için', 'Polis istediği için'], 1, 'Kurallar, yol kullanıcılarının güvenle ve düzenle hareket edebilmesi için vardır.'),
];
